source.docstring:
Two quadratic forms over a ring `R` are equivalent
if there exists an isometric equivalence between them:
a linear equivalence that transforms one quadratic form into the other.

concepts.statement:
∀ {R : Type u_1} [inst : Semiring R] {S : Type u_2} [inst_1 : Semiring S] {R₂ : Type u_3}
  [inst_2 : Semiring R₂] {S₂ : Type u_4} [inst_3 : Semiring S₂] {M : Type u_5} {N : Type u_6}
  {P : Type u_7} [inst_4 : AddCommMonoid M] [inst_5 : AddCommMonoid N] [inst_6 : AddCommMonoid P]
  [inst_7 : Module R M] [inst_8 : Module S N] [inst_9 : Module R₂ P] [inst_10 : Module S₂ P]
  [inst_11 : SMulCommClass S₂ R₂ P] {ρ₁₂ : R →+* R₂} {σ₁₂ : S →+* S₂}
  {f g : M →ₛₗ[ρ₁₂] N →ₛₗ[σ₁₂] P}, (∀ (m : M) (n : N), (f m) n = (g m) n) → f = g

