  [inst_1 : Fintype n] [inst_2 : Fintype m] [inst_3 : DecidableEq n] {M₁ : Type u_5} {M₂ : Type u_6}
  [inst_4 : AddCommMonoid M₁] [inst_5 : AddCommMonoid M₂] [inst_6 : Module R M₁]
  [inst_7 : Module R M₂] (v₁ : Basis n R M₁) (v₂ : Basis m R M₂) {M₃ : Type u_7}
